<h2>Announcements</h2><div class="tablewrap"><table><tr><th>Title</th><th>Posted By</th><th>Status</th><th>Visitor acknowledgements</th><th>Member acknowledgments</th><th>Actions</th></tr><?php foreach($posts as $p): $isDeleted = $p['deleted_at'] !== null; $isExpired = $p['expires_at'] !== null && $p['expires_at'] <= $now; $isPublicPublished = $p['status'] === 'published' && (!$p['published_at'] || $p['published_at'] <= $now); ?><tr><td><?=e($p['title'])?><?php if($p['is_pinned']): ?> <strong class="pin-indicator">Pinned</strong><?php endif; ?></td><td><?=e($p['author'])?> · <?=e(role_label($p['author_role']??''))?></td><td><?=e($p['status'])?><?php if($isDeleted): ?> · <strong class="lifecycle-state">Soft deleted</strong><?php elseif($p['archive_reason']==='expired'): ?> · <strong class="lifecycle-state">Expired (kept archived)</strong><?php elseif($p['archived_at']): ?> · <strong class="lifecycle-state">Manually archived</strong><?php elseif($isExpired && $isPublicPublished): ?> · <strong class="lifecycle-state">Expired (archived)</strong><?php endif; ?></td><td><?=e($p['upvotes'])?></td><td><?=e($p['member_acknowledgments'])?></td><td><?php if(!$isDeleted): ?><a href="announcement-form?id=<?=$p['id']?>">Edit</a> · <a href="announcement-history?id=<?=$p['id']?>">History</a> · <form class="inline-form" method="post" action="pin-announcement"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><input type="hidden" name="pinned" value="<?=$p['is_pinned']?'0':'1'?>"><button class="text-action" type="submit"><?=$p['is_pinned']?'Unpin':'Pin'?></button></form><?php if($canManageArchive && $isPublicPublished): ?> · <form class="inline-form" method="post" action="archive-announcement"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><input type="hidden" name="archive_action" value="<?=$p['archived_at']?'unarchive':'archive'?>"><button class="text-action" type="submit"><?=$p['archived_at']?'Unarchive':'Archive'?></button></form><?php endif; ?> · <form class="inline-form" method="post" action="delete-announcement" onsubmit="return confirm('Move this announcement to deleted items?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="text-action" type="submit">Delete</button></form><?php endif; ?><?php if($canManageArchive): ?> · <form class="inline-form" method="post" action="delete-permanently" onsubmit="return confirm('Permanently delete this announcement, its revisions, acknowledgments, votes, and unshared uploaded files? This cannot be undone.')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="text-action destructive-action" type="submit">Delete permanently</button></form><?php endif; ?></td></tr><?php endforeach; ?></table></div>
<?php if(is_admin()): ?><h2>Officer Accounts</h2><div class="tablewrap"><table><tr><th>Name</th><th>Login email</th><th>Role</th><th>Recovery</th></tr><?php foreach($users as $account): ?><tr><td><?=e($account['name'])?></td><td><?=e($account['email'])?></td><td><?=e(role_label($account['role']))?></td><td><form method="post" action="reset-password" onsubmit="return confirm('Restore this account to its initial password?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="user_id" value="<?=$account['id']?>"><button class="upvote" type="submit">Restore initial password</button></form></td></tr><?php endforeach; ?></table></div><?php endif; ?>
<h2>Recent Reports & Concerns</h2><div class="tablewrap"><table><tr><th>Type</th><th>Subject</th><th>Email</th><th>Status</th><th>Action</th></tr><?php foreach($reports as $r): ?><tr><td><?=e($r['type'])?></td><td><?=e($r['subject'])?></td><td><?=e($r['email'])?></td><td><?=e($r['status'])?></td><td><a href="report?id=<?=$r['id']?>">View</a></td></tr><?php endforeach; ?></table></div>
